"use strict";

module.exports = function constantsProbe() {
  const constants = require("constants");
  return {
    ok:
      Object.isFrozen(constants) &&
      Object.isFrozen(constants.fs) &&
      typeof constants.F_OK === "number" &&
      typeof constants.SIGINT === "number",
    summary: [
      "constants:" + typeof constants.F_OK,
      Object.isFrozen(constants.fs),
      typeof constants.SIGINT,
    ].join("/"),
  };
};
